import{_ as l,C as i,o as e,c as n,a2 as a,b as d,w as r,a as s,E,a3 as g}from"./chunks/framework.BBdhqAg0.js";const f=JSON.parse('{"title":"조직 체계 관리","description":"","frontmatter":{},"headers":[],"relativePath":"hr-manage/organization.md","filePath":"hr-manage/organization.md","lastUpdated":1793026459000}'),C={name:"hr-manage/organization.md"};function B(c,t,h,u,A,_){const o=i("Mermaid");return e(),n("div",null,[t[1]||(t[1]=a('<h1 id="조직-체계-관리" tabindex="-1">조직 체계 관리 <a class="header-anchor" href="#조직-체계-관리" aria-label="Permalink to &quot;조직 체계 관리&quot;">​</a></h1><blockquote><p><strong>조직 체계 관리</strong>는 회사의 부서 계층 구조, 직급·직위·직책 및 임원 직위 체계를 정의하고, 이를 바탕으로 전사 조직도를 시각화하여 체계적인 인력 및 결재선을 지원하는 기초 관리 모듈입니다.</p></blockquote><ul><li><strong>메뉴 위치</strong>: <code>본사 관리 &gt; 인사 조직 관리 &gt; 조직 체계 관리</code> (<code>/hr-manage/department</code>, <code>grade</code>, <code>position</code>, <code>duty</code>, <code>executive-rank</code>, <code>org-chart</code>)</li><li><strong>관리 대상</strong>: 부서 관리자, 인사 담당자, 시스템 관리자</li></ul>',3)),(e(),d(g,null,{default:r(()=>[E(o,{id:"mermaid-20",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5B%22%F0%9F%8F%A2%20%EB%B6%80%EC%84%9C%20%EC%A0%95%EB%B3%B4%20%EA%B4%80%EB%A6%AC%3Cbr%3E(%EA%B3%84%EC%B8%B5%20%ED%8A%B8%EB%A6%AC%20%26%20%EB%B6%80%EC%84%9C%20%EC%B1%85%EC%9E%84%EC%9E%90)%22%5D%20--%3E%20E%5B%22%F0%9F%8C%B3%20%EC%A1%B0%EC%A7%81%EB%8F%84%20(Org%20Chart)%3Cbr%3E(%EC%A0%84%EC%82%AC%20%EC%8B%9C%EA%B0%81%ED%99%94%20%EB%B0%8F%20%EB%B6%80%EC%84%9C%EB%B3%84%20%EC%9D%B8%EC%9B%90)%22%5D%0A%20%20%20%20B%5B%22%F0%9F%93%88%20%EC%A7%81%EA%B8%89%20(Job%20Grade)%3Cbr%3E(%EC%97%AD%ED%95%A0%C2%B7%EB%B3%B4%EC%83%81%20%EB%8B%A8%EA%B3%84)%22%5D%20--%3E%20E%0A%20%20%20%20C%5B%22%F0%9F%8E%96%EF%B8%8F%20%EC%A7%81%EC%9C%84%20(Position)%3Cbr%3E(%EC%A0%84%EB%AC%B8%EC%84%B1%C2%B7%ED%98%B8%EC%B9%AD)%22%5D%20--%3E%20E%0A%20%20%20%20D%5B%22%F0%9F%92%BC%20%EC%A7%81%EC%B1%85%20(Duty%20Title)%3Cbr%3E(%ED%8C%80%EC%9E%A5%2C%20%EB%B3%B8%EB%B6%80%EC%9E%A5%2C%20CEO)%22%5D%20--%3E%20E%0A%20%20%20%20D%20--%3E%20F%5B%22%E2%9A%A1%20%EC%A0%84%EC%9E%90%EA%B2%B0%EC%9E%AC%EC%84%A0%20%EC%9E%90%EB%8F%99%20%EC%82%B0%EC%B6%9C%22%5D%0A"})]),fallback:r(()=>[...t[0]||(t[0]=[s(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=a('<h2 id="_1-부서-정보-관리-department" tabindex="-1">1. 부서 정보 관리 (Department) <a class="header-anchor" href="#_1-부서-정보-관리-department" aria-label="Permalink to &quot;1. 부서 정보 관리 (Department)&quot;">​</a></h2><p>부서는 회사의 기능별 조직 단위를 정의하며, 상위 부서 지정을 통해 무제한 계층 트리(Tree) 구조를 형성합니다.</p><ul><li><strong>계층 레벨 자동 계산</strong>: 상위 부서 선택 시 해당 부서의 레벨이 자동으로 연산되며, 상위 부서가 변경될 경우 하위 조직의 레벨도 연쇄 갱신됩니다.</li><li><strong>순환 참조 방지</strong>: 자기 자신을 상위 부서로 지정하거나 상·하위 간 순환 참조가 발생하지 않도록 유효성 검사가 적용되어 있습니다.</li><li><strong>부서 책임자(Manager) 지정</strong>: 각 부서의 장(부서장/팀장)을 임직원 목록에서 지정하며, 전자결재 시 부서 내 1차 승인권자로 자동 연결됩니다.</li></ul><table tabindex="0"><thead><tr><th style="text-align:left;">주요 필드</th><th style="text-align:left;">설명</th><th style="text-align:left;">비고</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>상위 부서</strong></td><td style="text-align:left;">소속된 상위 조직 단위</td><td style="text-align:left;">최상위 부서인 경우 미지정 (Level 1)</td></tr><tr><td style="text-align:left;"><strong>부서명</strong></td><td style="text-align:left;">공식 부서 명칭 (예: 경영지원팀, 개발기획본부)</td><td style="text-align:left;">필수 입력</td></tr><tr><td style="text-align:left;"><strong>주요 업무</strong></td><td style="text-align:left;">부서의 핵심 R&amp;R 및 직무 설명</td><td style="text-align:left;">선택 입력</td></tr><tr><td style="text-align:left;"><strong>책임자</strong></td><td style="text-align:left;">부서 책임자 (<code>company.Staff</code>)</td><td style="text-align:left;">전자결재 자동 결재선의 기준</td></tr></tbody></table><h2 id="_2-직급-·-직위-·-직책-체계" tabindex="-1">2. 직급 · 직위 · 직책 체계 <a class="header-anchor" href="#_2-직급-·-직위-·-직책-체계" aria-label="Permalink to &quot;2. 직급 · 직위 · 직책 체계&quot;">​</a></h2><p>IBS는 인사 평가, 보상, 결재 권한의 혼선을 방지하기 위해 <strong>직급(Grade)</strong>, <strong>직위(Position)</strong>, **직책(Duty)**을 명확히 분리하여 관리합니다.</p><h3 id="직급-job-grade" tabindex="-1">직급 (Job Grade) <a class="header-anchor" href="#직급-job-grade" aria-label="Permalink to &quot;직급 (Job Grade)&quot;">​</a></h3><ul><li>조직 내에서 개인의 역할, 책임, 성장 단계 및 보상 수준을 일관된 기준으로 관리하는 체계입니다.</li><li>최소 근속 연수와 승급 기준표(<code>PromotionPolicy</code>)와 연계되어 승진 심사 대상 선발의 기준이 됩니다.</li></ul><h3 id="직위-position" tabindex="-1">직위 (Position) <a class="header-anchor" href="#직위-position" aria-label="Permalink to &quot;직위 (Position)&quot;">​</a></h3><ul><li>대외적 호칭 및 전문성 수준을 나타냅니다. (예: 사원, 대리, 과장, 차장, 부장)</li><li>하나의 직위에는 복수의 직급 단계가 매핑될 수 있습니다.</li></ul><h3 id="직책-duty-title" tabindex="-1">직책 (Duty Title) <a class="header-anchor" href="#직책-duty-title" aria-label="Permalink to &quot;직책 (Duty Title)&quot;">​</a></h3><ul><li>현재 맡고 있는 관리 및 지휘 책임입니다. (예: 팀장, 본부장, 부문장, 대표이사)</li><li><strong>전자결재 자동 결재선 산출의 핵심 기준</strong>으로 활용됩니다.</li></ul><h2 id="_3-임원-직위-관리-executive-rank" tabindex="-1">3. 임원 직위 관리 (Executive Rank) <a class="header-anchor" href="#_3-임원-직위-관리-executive-rank" aria-label="Permalink to &quot;3. 임원 직위 관리 (Executive Rank)&quot;">​</a></h2><p>등기 및 비등기 임원에 대한 특화 직위 체계(상무, 전무, 부사장, 사장, 부회장, 회장 등)를 정의하며, 이사회 및 대표이사 전결 규정과 연동됩니다.</p><h2 id="_4-전사-조직도-org-chart" tabindex="-1">4. 전사 조직도 (Org Chart) <a class="header-anchor" href="#_4-전사-조직도-org-chart" aria-label="Permalink to &quot;4. 전사 조직도 (Org Chart)&quot;">​</a></h2><p>등록된 부서 계층과 부서별 배속된 임직원(정규직/계약직/임원)의 현황을 실시간 다이어그램으로 시각화합니다.</p><ul><li><strong>부서별 인원 집계</strong>: 부서 단위별 현재 재직 인원수가 자동으로 카운트됩니다.</li><li><strong>책임자 및 구성원 표출</strong>: 부서장을 최상단에 강조 표시하고 소속 팀원들의 직위/직책을 한눈에 조회할 수 있습니다.</li><li><strong>조직도 검색</strong>: 특정 부서명이나 직원명을 검색하여 조직 내 위치를 빠르게 확인할 수 있습니다.</li></ul>',17))])}const p=l(C,[["render",B]]);export{f as __pageData,p as default};
